const req = $('🚀 Webhook (Regenerar)').item.json.body;
const client = $('📋 Leer Cliente').first().json;
const files = items.map(item => item.json);

const brutoUrl = `https://vtlxfpthqpqkgfdiqqwn.supabase.co/storage/v1/object/public/loopra/${client.id}/banco_bruto/`;
const procesadoUrl = `https://vtlxfpthqpqkgfdiqqwn.supabase.co/storage/v1/object/public/loopra/${client.id}/banco_procesado/`;

const imageFiles = files.filter(f => f.name && f.name !== '.emptyFolderPlaceholder' && /\.(jpg|jpeg|png|webp)$/i.test(f.name));
const videoFiles = files.filter(f => f.name && f.name !== '.emptyFolderPlaceholder' && /\.(mp4|mov|avi|webm|mkv)$/i.test(f.name));

let selectedFile = null;
if (req.content_type === 'REEL') {
  if (videoFiles.length === 0) throw new Error('No hay vídeos disponibles en banco_bruto para crear un REEL.');
  selectedFile = videoFiles[0];
} else {
  if (imageFiles.length === 0) throw new Error('No hay imágenes disponibles en banco_bruto para crear un POST/HISTORIA.');
  selectedFile = imageFiles[0];
}

const batch = [{
  index: 0,
  fileName: selectedFile.name,
  imageUrl: brutoUrl + selectedFile.name,
  finalUrl: procesadoUrl + selectedFile.name,
  contentType: req.content_type,
  platform: req.platform || ['instagram'],
  proposedDate: req.proposed_date,
  proposedTime: req.proposed_time,
  slotLabel: req.slot_label || 'Regenerado a petición'
}];

return [{ json: { client, batch } }];

const raw = items[0].json;
const batch = $('⚙️ Seleccionar Media Libre').first().json.batch;
const client = $('⚙️ Seleccionar Media Libre').first().json.client;

if (raw.choices && raw.choices[0] && raw.choices[0].message.refusal) {
  throw new Error('OpenAI ha bloqueado la imagen por sus políticas de seguridad: ' + raw.choices[0].message.refusal);
}

let aiPosts;
try {
  aiPosts = JSON.parse(raw.choices[0].message.content).posts;
} catch(e) {
  throw new Error('Error parseando OpenAI: ' + e.message);
}

return aiPosts.map(aiPost => {
  const batchItem = batch[aiPost.index];
  const copyFinal = aiPost.cta ? aiPost.copy_text + '\n\n👉 ' + aiPost.cta : aiPost.copy_text;
  return {
    json: {
      client_id: client.id,
      status: 'PENDING_APPROVAL',
      content_type: aiPost.content_type,
      copy_text: copyFinal,
      hashtags: aiPost.hashtags,
      platform: batchItem.platform,
      image_url: batchItem.finalUrl,
      proposed_date: batchItem.proposedDate,
      proposed_time: batchItem.proposedTime,
      ai_analysis: { mood: aiPost.ai_mood, slot_label: batchItem.slotLabel, model: 'gpt-4o', generated_at: new Date().toISOString() }
    }
  };
});

const batch = $('⚙️ Seleccionar Media Libre').first().json.batch;
const client = $('⚙️ Seleccionar Media Libre').first().json.client;
const fileName = batch[0].fileName;

return [{
  json: {
    bucketId: 'loopra',
    sourceKey: `${client.id}/banco_bruto/${fileName}`,
    destinationKey: `${client.id}/banco_procesado/${fileName}`
  }
}];
